import {words,resolveVote,scoresFor,validClue} from './engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dialog=$('#dialog'); let game=null, totals=Array(6).fill(0), recent=[], names=Array.from({length:6},(_,i)=>`Player ${i+1}`), roundNumber=0;
function rand(n){const x=new Uint32Array(1);crypto.getRandomValues(x);return x[0]%n;}
const pick=a=>a[rand(a.length)];
function showModal(html){$('#dialog-content').innerHTML=html;dialog.showModal();}
function players(){const count=game?.n??Number($('#count').value);$('#players').innerHTML=Array.from({length:count},(_,i)=>`<article class="player ${game?.turn===i?'active':''}"><div class="portrait" role="img" aria-label="Anonymous shadow player wearing glasses and holding secret cards"><span class="seat">SEAT 0${i+1}</span></div><div class="player-info"><div>${game?`<strong>${esc(names[i])}</strong>`:`<input class="name-input" aria-label="Name for player ${i+1}" data-name="${i}" maxlength="20" value="${esc(names[i])}">`}<small>${(game?.mode??$('#mode').value)==='solo'?(i===0?'YOU':'PRACTICE BOT'):'AT THE TABLE'}</small></div><span class="symbol">◇</span></div></article>`).join('');document.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>{names[Number(el.dataset.name)]=el.value.trim()||`Player ${Number(el.dataset.name)+1}`;});}
function scoreboard(){$('#scoreboard').innerHTML=names.slice(0,game.n).map((n,i)=>`<div class="score-row"><span>${esc(n)}</span><b>${totals[i]} pts</b></div>`).join('');}
function setStage(title,description,body=''){$('#stage').innerHTML=`<div class="stage-box"><h3>${title}</h3><p>${description}</p>${body}</div>`;players();scoreboard();}
function button(id,label,cls='primary'){return `<button id="${id}" class="${cls}">${label}</button>`;}
function start(){let available=words.filter(w=>!recent.includes(w.answer));if(!available.length){recent=[];available=words;}const word=pick(available);recent.push(word.answer);game={n:Number($('#count').value),mode:$('#mode').value,word,impostor:rand(Number($('#count').value)),turn:0,round:1,maxRounds:Number($('#count').value)===4?2:3,clues:[],votes:[],eligible:[],tieStage:0,messages:[],phase:'reveal'};roundNumber++;$('#setup').hidden=true;$('#play-area').hidden=false;$('#table-title').textContent=`Round ${roundNumber}. Keep a straight face.`;$('#phase-pill').textContent='Private card reveal';revealGate();}
function revealGate(){setStage(`Your card, ${esc(names[game.turn])}.`,game.mode==='local'?'Pass the device to this player. Everyone else, look away.':'Your role stays hidden until the final reveal.',button('reveal','Turn over my card ↗'));$('#reveal').onclick=()=>{const imp=game.turn===game.impostor;showModal(`<p class="eyebrow">FOR ${esc(names[game.turn])} ONLY</p><div class="secret-card ${imp?'impostor':''}"><small>${imp?'YOU ARE THE IMPOSTOR':'YOU ARE ON THE TEAM'}</small><strong>${esc(imp?game.word.hint:game.word.answer)}</strong><p>${imp?'This is your broad hint. Listen carefully and blend in.':'Remember this word. When everyone is ready, say something related without saying the word itself.'}</p></div><div class="actions">${button('hide-card','Hide card & continue')}</div>`);$('#hide-card').onclick=()=>{dialog.close();game.turn++;if(game.mode==='solo'||game.turn>=game.n){game.turn=0;game.phase='ready';everyoneReady();}else revealGate();};};}
function everyoneReady(){game.turn=null;setStage('Everyone has seen their card.', 'Now take turns adding any word or short phrase related to your secret word. For example, for Bus: wheels, children, school. Each entry appears for everyone with the player’s name. Keep the secret word itself hidden.',button('start-words','Start related-word round ↗'));$('#start-words').onclick=()=>{game.turn=0;game.phase='clues';clueTurn();};}
function ledger(){$('#round-count').textContent=`WORD ROUND ${game.round} / ${game.maxRounds}`;$('#clues').innerHTML=game.clues.map(c=>`<div class="clue-row"><b>${esc(names[c.player])}</b><span>${esc(c.text)}</span><small>R${c.round}</small></div>`).join('')||'<p class="muted">Everyone sees their card first. Then the related words appear here.</p>';$('#clues').scrollTop=$('#clues').scrollHeight;}
function botClue(i){const used=game.clues.map(c=>c.text.toLowerCase());if(i!==game.impostor){return game.word.clues.find(c=>!used.includes(c))??pick(game.word.clues);}const broad={Vehicle:['journey','outside','moving','travel','useful','speed'],Food:['tasty','meal','favourite','sharing','hungry','treat'],Animal:['nature','alive','wildlife','creature','outdoors','habitat'],Place:['visit','people','trip','memories','somewhere','weekend'],Fruit:['fresh','snack','healthy','market','natural','basket'],'Everyday object':['useful','home','practical','carry','daily','handy'],Sport:['playing','energy','practice','competition','active','fun']};return (broad[game.word.hint]??['familiar','popular','everyday']).find(c=>!used.includes(c))??'familiar';}
function clueTurn(){while(game.mode==='solo'&&game.turn>0&&game.turn<game.n){game.clues.push({player:game.turn,text:botClue(game.turn),round:game.round});game.turn++;}if(game.turn>=game.n){game.round++;game.turn=0;if(game.round>game.maxRounds){discussion();return;}}$('#phase-pill').textContent=`Related words · round ${game.round}`;ledger();setStage(`${esc(names[game.turn])}, add a related word.`,game.mode==='local'?'Say anything related to your secret word. Your entry will be visible to everyone. Do not say the secret word itself.':'Say anything related to your secret word. Everyone will see your entry beside your name.',`<form id="clue-form" class="clue-form"><input id="clue-input" aria-label="Your related word" placeholder="Type a related word or phrase…" maxlength="60" required autocomplete="off">${button('submit-clue','Share word ↗')}</form><p id="clue-error" class="error" role="alert"></p>`);$('#clue-form').onsubmit=e=>{e.preventDefault();const t=$('#clue-input').value.trim();if(!validClue(t,game.word.answer)){$('#clue-error').textContent='Use 1–60 characters and keep the secret answer out of your entry.';return;}game.clues.push({player:game.turn,text:t,round:game.round});game.turn++;clueTurn();};}
function suspicion(i){const clues=game.clues.filter(c=>c.player===i);return clues.reduce((sum,c)=>sum+(game.word.clues.includes(c.text.toLowerCase())?0:1),0)/Math.max(1,clues.length);}
function discussion(){game.phase='discussion';game.turn=null;game.round=game.maxRounds;ledger();$('#phase-pill').textContent='The meeting';setStage('Something doesn’t add up.',game.mode==='solo'?'Compare everyone’s related words. Practice bots use scripted words, not a live AI model.':'Talk it out together, or leave notes below. Everyone can see the discussion.',`<div id="chat-list" class="chat-list"></div><form id="chat-form" class="clue-form">${game.mode==='local'?`<select id="speaker" aria-label="Speaker">${names.slice(0,game.n).map((n,i)=>`<option value="${i}">${esc(n)}</option>`).join('')}</select>`:''}<input id="chat-input" aria-label="Discussion message" placeholder="Who sounded a little too vague?" maxlength="180" required><button class="secondary">Send</button></form><div class="actions">${button('begin-vote','Ready to vote ↗')}</div>`);if(game.mode==='solo'&&!game.messages.length){for(let i=1;i<game.n;i++){const others=Array.from({length:game.n},(_,j)=>j).filter(j=>j!==i);const target=i===game.impostor?pick(others):others.sort((a,b)=>suspicion(b)-suspicion(a))[0];game.messages.push({player:i,text:`${names[target]}'s words felt broad to me. What do you think?`});}}renderChat();$('#chat-form').onsubmit=e=>{e.preventDefault();const text=$('#chat-input').value.trim();if(!text)return;game.messages.push({player:game.mode==='solo'?0:Number($('#speaker').value),text});$('#chat-input').value='';renderChat();};$('#begin-vote').onclick=()=>{if(game.tieStage!==2)game.eligible=Array.from({length:game.n},(_,i)=>i);beginVote();};}
function renderChat(){$('#chat-list').innerHTML=game.messages.map(m=>`<div class="chat-message"><b>${esc(names[m.player])}</b>${esc(m.text)}</div>`).join('');$('#chat-list').scrollTop=$('#chat-list').scrollHeight;}
function beginVote(){game.phase='vote';game.turn=0;game.votes=[];voteTurn();}
function botVote(i){let eligible=game.eligible.filter(x=>x!==i);if(!eligible.length)return null;if(i===game.impostor)return pick(eligible);const max=Math.max(...eligible.map(suspicion));return pick(eligible.filter(x=>suspicion(x)===max));}
function voteTurn(){if(game.mode==='solo'&&game.turn>0){for(let i=1;i<game.n;i++)game.votes.push(botVote(i));finishVote();return;}if(game.turn>=game.n){finishVote();return;}$('#phase-pill').textContent=game.tieStage?'Tie-break vote':'Private voting';setStage(`${esc(names[game.turn])}, who is bluffing?`,game.mode==='local'?'Pass the device privately. Votes stay hidden until everyone has chosen.':'Choose carefully. You cannot vote for yourself.',`<div class="vote-options">${game.eligible.filter(i=>i!==game.turn).map(i=>`<button class="vote-option" data-vote="${i}">${esc(names[i])}</button>`).join('')||'<button class="vote-option" data-vote="skip">Abstain (only your own seat remains)</button>'}</div>`);document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{game.votes.push(b.dataset.vote==='skip'?null:Number(b.dataset.vote));game.turn++;voteTurn();});}
function finishVote(){const result=resolveVote(game.votes,game.eligible);game.turn=null;if(result.winner!==null){finish(result.winner,result.counts);return;}if(game.tieStage===2){finish(null,result.counts);return;}game.tieStage++;game.eligible=result.tied;const extra=game.tieStage===2;setStage('The table is divided.',`Tied: ${result.tied.map(i=>esc(names[i])).join(', ')}. ${extra?'One extra related-word round, then a final vote.':'Revote among the tied players.'}`,button('tie-next',extra?'One more word round ↗':'Revote ↗'));$('#tie-next').onclick=()=>{if(extra){game.round=game.maxRounds+1;game.maxRounds++;game.turn=0;game.phase='clues';clueTurn();}else beginVote();};}
function finish(accused,counts){game.phase='result';const deltas=scoresFor(game.n,game.impostor,accused);deltas.forEach((x,i)=>totals[i]+=x);$('#phase-pill').textContent='Cards on the table';const caught=accused===game.impostor;setStage(accused===null?'A perfect stalemate.':caught?'Caught in the act.':'The bluff paid off.',accused===null?'The final vote tied. Everyone gets zero points this round.':`${esc(names[accused])} was accused. ${caught?'The team found the impostor.':'The real impostor slipped away.'}`,`<p><strong>${esc(names[game.impostor])}</strong> was the impostor. The word was <strong>${esc(game.word.answer)}</strong>; the hint was <strong>${esc(game.word.hint)}</strong>.</p><div class="result-grid">${names.slice(0,game.n).map((n,i)=>`<div>${esc(n)} ${i===game.impostor?'◇':''}<b>${deltas[i]>0?'+':''}${deltas[i]} pts</b><br><small>${counts[i]??0} vote(s) in final ballot</small></div>`).join('')}</div><div class="actions">${button('again','Deal another round ↗')}${button('lobby','Back to the table','secondary')}</div>`);$('#again').onclick=start;$('#lobby').onclick=()=>{game=null;$('#setup').hidden=false;$('#play-area').hidden=true;$('#stage').innerHTML='';$('#table-title').textContent='Take a seat.';$('#phase-pill').textContent='Waiting for players';players();};}
$('#deal').onclick=start;$('#count').onchange=players;$('#mode').onchange=players;
$('#rules-button').onclick=()=>{showModal(`<p class="eyebrow">THE HOUSE RULES</p><h2>Trust is the whole game.</h2><ul><li>4–6 players. One impostor gets a broad hint; the team gets a familiar secret word.</li><li>Everyone checks their private card first. Then each player says a word or phrase related to the secret word, visible to everyone beside their name. Play two word rounds with four players, three with five or six.</li><li>Discuss your suspicions, then vote privately. No voting for yourself.</li><li>A tie means a revote among tied players. Another tie adds one related-word round and a final vote. A final tie earns everyone zero.</li><li>Catch the impostor: each teammate gets +20. Accuse the wrong person: teammates get −10; impostor gets +30.</li><li>First-edition default: a caught impostor earns zero. Scores last until the page is refreshed.</li></ul><p>Pass-and-play relies on players looking away for private cards and votes. Online rooms are not included in this edition.</p>${button('close-rules','Take my seat')}`);$('#close-rules').onclick=()=>dialog.close();};
dialog.addEventListener('cancel',e=>{if(game?.phase==='reveal'&&!$('#close-rules'))e.preventDefault();});players();

